def solve():
    import sys
    input = sys.stdin.read
    data = input().splitlines()

    h, w, n = map(int, data[0].split())
    board = [list(data[i + 1]) for i in range(h)]
    commands = [data[h + 1 + i].split() for i in range(n)]
    commands = [(cmd[0], int(cmd[1])) for cmd in commands]

    def is_valid(x, y):
        return 0 <= x < h and 0 <= y < w

    # Initial position at bottom-left corner of the board
    x, y = h - 1, 0

    # Function to simulate the drawing of the entire board at a given timestep
    def simulate(timestep):
        sim_board = [['.' for _ in range(w)] for _ in range(h)]
        cx, cy = h - 1, 0
        for direction, distance in commands:
            if direction == 'up':
                for _ in range(distance):
                    cx -= 1
            elif direction == 'down':
                for _ in range(distance):
                    cx += 1
            elif direction == 'left':
                for _ in range(distance):
                    cy -= 1
            elif direction == 'right':
                for _ in range(distance):
                    cy += 1
            # Mark the path in the simulation board
            sim_board[cx][cy] = '#'
        return sim_board

    # Function to get the earliest and latest time step when the marker can dry out
    def find_times():
        # Initial valid times
        min_time, max_time = float('inf'), float('-inf')

        # Simulate for each timestep from 0 to n-1
        for timestep in range(n):
            sim_board = simulate(timestep)
            if sim_board == board:
                min_time = min(min_time, timestep)
                max_time = max(max_time, timestep)

        if min_time == float('inf') or max_time == float('-inf'):
            return -1, -1
        return min_time, max_time

    min_time, max_time = find_times()
    print(min_time, max_time)
